    high_supply = supply >= 22
    low_supply = supply <= 17

    if prev_bids:
        highest_prev = max(prev_bids)
        modest_prev = max([b for b in prev_bids if b < 120.0], default=0.0)
    else:
        highest_prev = 0.0
        modest_prev = 0.0

    danger = hp <= 2 or no_water_days >= 2
    caution = hp <= 4 or no_water_days >= 1

    if danger:
        if cindy_like:
            bid = 18.0 if high_supply else 32.0
        else:
            target = modest_prev + 3.0 if modest_prev > 0 else 36.0
            if low_supply:
                target += 8.0
            bid = target
        return float(min(budget, max(0.0, bid)))

    if caution:
        if cindy_like:
            bid = 10.0 if high_supply else 22.0
        else:
            target = modest_prev + 2.0 if modest_prev > 0 else 24.0
            if low_supply:
                target += 6.0
            bid = target
        return float(min(budget, max(0.0, bid)))

    if cindy_like:
        if high_supply:
            bid = 3.0
        elif low_supply:
            bid = 9.0
        else:
            bid = 6.0
    else:
        if modest_prev > 0:
            bid = min(20.0, modest_prev + 1.5)
        else:
            bid = 7.0 if high_supply else 11.0

    if day >= 8 and hp >= 6:
        bid *= 0.8

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 40.0

    # Aggressive if low HP or scarce supply
    if my_status['hp'] <= 3 or supply < 18:
        bid = max(avg_prev * 1.1, 60.0)
    else:
        bid = max(avg_prev * 0.9, 35.0)

    return min(my_status['budget'], float(bid))
